style:
 * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      font-family: Arial, sans-serif;
    }

    body {
      background: #f3f4f6;
      display: flex;
      justify-content: center;
      padding: 40px 0;
    }

    .profile-banner {
      width: 100%;
     
      background: white;
      border-radius: 1rem;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
      overflow: hidden;
      transition: all 0.3s ease;
    }

    .profile-banner:hover {
      box-shadow: 0 8px 20px rgba(0,0,0,0.2);
    }

    /* Banner */
    .banner {
      position: relative;
      height: 16rem;
      background-color: #d1d5db;
      overflow: hidden;
    }

    .banner img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .banner::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.3), transparent);
      opacity: 0.6;
    }

    .edit-btn {
      position: absolute;
      top: 1rem;
      right: 1rem;
      background: rgba(0,0,0,0.3);
      padding: 0.5rem;
      border-radius: 50%;
      color: white;
      cursor: pointer;
      backdrop-filter: blur(4px);
      opacity: 0;
      transition: all 0.3s;
      border: none;
    }

    .banner:hover .edit-btn {
      opacity: 1;
    }

    .edit-btn svg {
      width: 1.25rem;
      height: 1.25rem;
    }

    /* Profile Info */
    .profile-info {
      padding: 0 1.5rem 0.5rem 1.5rem;
      position: relative;
    }

    .profile-header {
      display: flex;
      flex-direction: column;
      align-items: center;
      margin-top: -4rem;
      margin-bottom: 1.5rem;
    }

    @media(min-width: 768px) {
      .profile-header {
        flex-direction: row;
        align-items: flex-end;
        margin-top: -5rem;
      }
    }

    /* Avatar */
    .avatar-container {
      position: relative;
      z-index: 10;
    }

    .avatar {
      width: 8rem;
      height: 8rem;
      border-radius: 50%;
      border: 6px solid white;
      box-shadow: 0 4px 6px rgba(0,0,0,0.2);
      overflow: hidden;
      background: white;
    }

    @media(min-width: 768px) {
      .avatar {
        width: 10rem;
        height: 10rem;
      }
    }

    .avatar img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .online-status {
      position: absolute;
      bottom: 1rem;
      right: 0.5rem;
      width: 1.25rem;
      height: 1.25rem;
      background: #22c55e;
      border: 4px solid white;
      border-radius: 50%;
    }

    @media(min-width: 768px) {
      .online-status {
        width: 1.5rem;
        height: 1.5rem;
        bottom: 1.25rem;
        right: 0.75rem;
      }
    }

    /* Text Info */
    .text-info {
      margin-top: 1rem;
      text-align: center;
      flex-grow: 1;
    }

    @media(min-width: 768px) {
      .text-info {
        margin-top: 0;
        margin-left: 1.5rem;
        text-align: left;
        margin-bottom: 0.5rem;
      }
    }

    .text-info h1 {
      font-size: 1.875rem;
      font-weight: bold;
      color: #111827;
      line-height: 1.2;
    }

    .text-info p {
      font-size: 1.125rem;
      font-weight: 500;
      color: #6b7280;
      margin-top: 0.25rem;
    }

    /* Action Buttons */
    .actions {
      margin-top: 1.5rem;
      display: flex;
      gap: 0.75rem;
    }

    .actions button {
      padding: 0.5rem 1.5rem;
      font-weight: 600;
      border-radius: 9999px;
      box-shadow: 0 1px 2px rgba(0,0,0,0.1);
      cursor: pointer;
      transition: background 0.2s;
      border: none;
    }

    .btn-follow {
      background: #2563eb;
      color: white;
    }

    .btn-follow:hover {
      background: #1d4ed8;
    }

    .btn-message {
      background: white;
      border: 1px solid #d1d5db;
      color: #374151;
    }

    .btn-message:hover {
      background: #f9fafb;
    }

    /* Stats Grid */
    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
      border-top: 1px solid #e5e7eb;
      padding-top: 1.5rem;
    }

    .stats div {
      text-align: center;
    }

    @media(min-width: 768px) {
      .stats div {
        text-align: left;
      }
    }

    .stats .number {
      font-size: 1.5rem;
      font-weight: bold;
      color: #1f2937;
    }

    .stats .label {
      font-size: 0.75rem;
      font-weight: 500;
      color: #6b7280;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

script:
(() => {
    const root = root_element;
    const list = root.querySelector("#payment-list");
    const viewAll = root.querySelector("#view-all-payments");
    const recentPayment = root.querySelector("#recent-payment");
    
    viewAll.textContent = frappe._("View All");
    recentPayment.textContent = frappe._("Recent Payments");
    if (!list) return;

    frappe.db.get_list("Sale Payment", {
        fields: [
            "name",
            "sale",
            "customer_name",
            "payment_type",
            "posting_date",
            "payment_amount",
            "balance",
            "outlet",
            "account_paid_to",
            "docstatus"
        ],
        order_by: "posting_date desc",
        limit: 5
    }).then(data => {
        list.innerHTML = "";

        if (!data.length) {
            list.innerHTML = `
                <li class="list-group-item text-center text-muted">
                    No payments found
                </li>
            `;
            return;
        }

        data.forEach(p => {
            let badgeClass = "bg-secondary";
            let statusText = "Draft";

            if (p.docstatus === 1 && p.balance === 0) {
                badgeClass = "bg-success";
                statusText = "Paid";
            } else if (p.balance > 0) {
                badgeClass = "bg-warning text-dark";
                statusText = "Pending";
            }

            list.insertAdjacentHTML("beforeend", `
                <li class="list-group-item d-flex justify-content-between align-items-center payment-item"
                    data-name="${p.name}"
                    style="cursor:pointer;">
                    <div>
                        <strong>
                  
                             ${p.name}
                        </strong>
     <div class="small text-muted">
                            ${p.customer_name} - 
                                       ${p.account_paid_to}
                        </div>
                        <small class="text-muted">
                            ${frappe.datetime.str_to_user(p.posting_date)}
                        </small>
                    </div>
                    <div>
                    <div>
                    <span class="badge fs-6 bg-secondary p-2 text-white">
                        ${frappe.format(p.payment_amount, {
                            fieldtype: "Currency"
                        })}
                    </span>
                    </div>
                
                    </div>
                </li>
            `);
        });

        // Click → open Sale Payment
        root.querySelectorAll(".payment-item").forEach(item => {
            item.onclick = () => {
                frappe.set_route("Form", "Sale Payment", item.dataset.name);
            };
        });
    });

    // View all Sale Payments
    if (viewAll) {
        viewAll.onclick = e => {
            e.preventDefault();
            frappe.set_route("List", "Sale Payment");
        };
    }
})();

